List<Enemy> enemies = new List<Enemy>();
// ... (suponemos que ya tiene elementos)

// foreach recorre cada elemento sin necesidad de índices
foreach (Enemy enemy in enemies)
{
    enemy.TakeDamage(10);
    Debug.Log(enemy.name);
}

// foreach con array
string[] nombres = { "Ana", "Luis", "Mia" };
foreach (string nombre in nombres)
{
    Debug.Log(nombre);
}

// foreach con Dictionary: usa KeyValuePair
Dictionary<string, int> stats = new Dictionary<string, int>();
stats["vida"] = 100;
stats["mana"] = 50;

foreach (KeyValuePair<string, int> par in stats)
{
    Debug.Log(par.Key + ": " + par.Value);
}

List<GameObject> proyectiles = new List<GameObject>();

// for con índice: útil cuando necesitas el índice durante la iteración
for (int i = 0; i < proyectiles.Count; i++)
{
    Debug.Log("Proyectil " + i + ": " + proyectiles[i].name);
}

// Cuándo usar for vs foreach:
// - Usa foreach cuando solo necesitas LEER o procesar cada elemento.
// - Usa for cuando necesitas el ÍNDICE del elemento durante la iteración.
// - IMPORTANTE: Si necesitas ELIMINAR elementos, itera la lista al revés
//   o usa una lista temporal; nunca modifiques la colección en un foreach.

// Iteración inversa para eliminar elementos de forma segura:
for (int i = proyectiles.Count - 1; i >= 0; i--)
{
    if (proyectiles[i] == null)
    {
        proyectiles.RemoveAt(i);
    }
}

Dictionary<string, float> cooldowns = new Dictionary<string, float>();
cooldowns["Fireball"] = 3.0f;
cooldowns["Heal"] = 5.0f;
cooldowns["Dash"] = 1.5f;

// Recorrer todos los pares clave-valor
foreach (KeyValuePair<string, float> kvp in cooldowns)
{
    Debug.Log(kvp.Key + " -> " + kvp.Value + "s");
}

// Recorrer solo las claves
foreach (string habilidad in cooldowns.Keys)
{
    Debug.Log("Habilidad: " + habilidad);
}

// Recorrer solo los valores
foreach (float tiempo in cooldowns.Values)
{
    Debug.Log("Cooldown: " + tiempo);
}

// También puedes usar var para simplificar el tipo
foreach (var kvp in cooldowns)
{
    Debug.Log(kvp.Key + ": " + kvp.Value);
}

